CSS='''*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#293f62;font:16px/1.75 system-ui,sans-serif}main{max-width:980px;margin:auto;padding:45px 28px 80px}a{color:#345e9b;text-underline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:10px 22px;font-size:14px;margin-bottom:40px}h1{font-size:clamp(30px,5vw,46px);line-height:1.15;letter-spacing:-1.4px;max-width:780px}h2{font-size:23px;margin:38px 0 12px;line-height:1.4}p,ul,ol{margin:14px 0}li{margin:8px 0}.meta{color:#71839f;font-size:14px;margin-top:20px}.card{display:block;background:white;border:1px solid #dce5f1;padding:22px;border-radius:14px;text-decoration:none;margin:14px 0}.card strong{display:block;font-size:20px}.card span{color:#71839f}table{width:100%;border-collapse:collapse;background:white;font-size:14px;display:block;overflow:auto}th,td{border:1px solid #dce5f1;padding:12px;text-align:left}pre{background:#233b64;color:#ecf5ff;padding:22px;border-radius:10px;overflow:auto}code{font-size:.9em;overflow-wrap:anywhere}footer{border-top:1px solid #dce5f1;padding-top:20px;margin-top:50px;font-size:13px;color:#71839f}.badge{display:inline-block;border-radius:40px;padding:5px 12px;background:#d7eee5;font-size:12px;margin-bottom:20px}'''
def page(title,body,sub=False):
 prefix='../' if sub else ''
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+' · ETAL Connect</title><style>'+CSS+'</style></head><body><main><nav><a href="'+prefix+'DOCUMENTACAO.html">Documentação</a><a href="'+prefix+'index.html">Abrir aplicativo</a><a href="'+prefix+'maps/bloco-principal.svg">Planta dos três andares</a></nav><span class="badge">ETAL CONNECT · EXPORTAÇÃO LOCAL</span><h1>'+escape(title)+'</h1><p class="meta">Exportado em 07/11/2026 · Protótipo independente · Dados demonstrativos</p>'+body+'<footer>Esta documentação preserva decisões da conversa para continuidade. Não constitui documentação oficial do IFRN, SUAP, NADIC ou do evento.</footer></main></body></html>'
report=ROOT/'exportacao/validacao.json'
if report.exists():
 data=json.loads(report.read_text())
 items=''.join('<li>'+escape(item)+'</li>' for item in data['checks_passed'])
 PAGES['validacao']=('Verificação da exportação','<p>Verificação realizada em '+escape(data['date'])+' no Chromium, abrindo diretamente o arquivo local com o contexto offline.</p><ul>'+items+'</ul><p>Erros JavaScript: 0. Requisições externas: 0. Links locais ausentes: 0. TypeScript: aprovado.</p><p>Essa verificação cobre o protótipo demonstrativo, sem validar autenticação institucional ou frequência oficial.</p>')
for slug,(title,body) in PAGES.items():
 (ROOT/'docs'/f'{slug}.html').write_text(page(title,body,True))
intro='<p>Abra o aplicativo por duplo clique em <a href="index.html">index.html</a>. Esta pasta reúne a demonstração HTML, o código-fonte editável, a base dos mapas e as decisões necessárias para continuar o projeto.</p>'
for slug,(title,_) in PAGES.items():intro+='<a class="card" href="docs/'+slug+'.html"><strong>'+escape(title)+'</strong><span>Ler documentação →</span></a>'
(ROOT/'DOCUMENTACAO.html').write_text(page('Tudo para continuar o ETAL Connect',intro))
print('Documentação HTML gerada: índice + '+str(len(PAGES))+' páginas.')
